// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint v, uint _decimals, address from, address[] memory _tos) public {
        vm.assume(_tos.length > 0);
        vm.assume(from != address(0));
        vm.assume(_decimals <= 18);
        // Deploy a helper that records the transferFrom call it receives
        TransferRecorder helper = new TransferRecorder();
        // c will call helper.transferFrom(...) with the encoded value
        c.transfer(from, address(helper), _tos, v, _decimals);
        // The assertion: helper.lastValue must equal v * 10 ** _decimals for the correct version,
        // but for the buggy version it equals v, so this fails when the fuzzer picks v and _decimals such that v * 10 ** _decimals != v.
        assertTrue(helper.lastValue() == v * 10 ** _decimals);
    }
}

contract TransferRecorder {
    uint public lastValue;
    function transferFrom(address, address, uint256 value) external returns (bool) {
        lastValue = value;
        return true;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 v, uint256 _decimals, address sender, address[] memory _tos) public {
        // 1. keep domain wide: avoid overflow in 10**_decimals and v*10**_decimals
        vm.assume(_tos.length > 0 && _tos.length <= 5);
        _decimals = bound(_decimals, 0, 18);
        uint256 maxV = type(uint256).max / (10 ** _decimals);
        v = bound(v, 1, maxV);
        // 2. deploy a recording adversarial callee that exposes received amounts
        Recorder recorder = new Recorder();
        address caddress = address(recorder);
        // caller funds (not needed for transfer, but harmless)
        vm.deal(sender, 0);
        vm.prank(sender);
        c.transfer(sender, caddress, _tos, v, _decimals);
        // 3. assert: the recorded amount equals v * 10**_decimals for both versions? No, the reference sets that, bug sets v.
        // We compare the recorded amount with the expected amount for the reference (scaled).
        uint256 scaled = v * 10 ** _decimals;
        // For the reference, recorder.received() MUST equal scaled. For the bug, it equals v ≠ scaled for some inputs.
        assertTrue(recorder.received() == scaled);
    }
}

contract Recorder {
    uint256 public received;
    function transferFrom(address, address, uint256 _value) external returns (bool) {
        received = _value;
        return true;
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(address from, address target, address[] memory tos, uint v, uint decimals) public {
        require(tos.length > 0);
        bool success = c.transfer(from, target, tos, v, decimals);
        assert(success != false);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address caddress, address[] memory _tos, uint v, uint _decimals) public payable {
        require(_tos.length > 0);
        bool reverted;
        try c.transfer(from, caddress, _tos, v, _decimals) { reverted = false; } catch { reverted = true; }
        assert(!reverted);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address caddress, address[] memory _tos, uint v, uint _decimals) public payable {
        require(_tos.length > 0);
        bool reverted; try c.transfer(from, caddress, _tos, v, _decimals) { reverted = false; } catch { reverted = true; }
        bool innerReverted;
        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        uint _value = v * 10 ** _decimals;
        // simulate the first inner call to check if it would revert
        try caddress.call(abi.encodeWithSelector(id, from, _tos[0], _value)) { innerReverted = false; } catch { innerReverted = true; }
        assert(!reverted != !innerReverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address caddress, address[] memory _tos, uint v, uint _decimals) public payable {
        require(_tos.length > 0);
        bool reverted; try c.transfer(from, caddress, _tos, v, _decimals) { reverted = false; } catch { reverted = true; }
        assert(!reverted || _tos.length == 0);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address token, address[] memory tos, uint v, uint decimals) public payable {
        require(tos.length > 0);
        bool reverted;
        try c.transfer(from, token, tos, v, decimals) returns (bool ret) {
            reverted = false;
            assert(ret == true);
        } catch {
            reverted = true;
        }
        assert(!reverted || (reverted && true));
    }
    receive() external payable {}
}
